#!/usr/bin/env bash
# le-sync LEZ environment (Sprint 6, M0). Source it, do not execute it:
#
#   source scripts/lez_env.sh
#
# Runs from the LEZ project directory (default ./lez, generated by `lgs new`).
# Override before sourcing: LEZ_DIR (project dir), LEZ_PROGRAM (program to deploy, default hello_world).
# RISC0_DEV_MODE=1 is set only inside these functions, for the local sequencer. Fake receipts: never
# use them for a real claim. Unset it again for anything else.
#
# Commands after sourcing:
#   lez_check             versions and prerequisites, no changes made
#   lez_new               create the project in $LEZ_DIR (once)
#   lez_setup             fetch and build LEZ, SPEL and the wallet (slow on a cold cache), then doctor
#   lez_build             build the guest programs
#   lez_up                start the local sequencer (port 3040) and show its status
#   lez_down              stop the local sequencer
#   lez_deploy [name]     deploy all programs, or one by name (default: $LEZ_PROGRAM)
#   lez_account           create a public account, keep its ID in $LEZ_ACCT
#   lez_call              run the hello example against $LEZ_ACCT, then read the account back
#   lez_record            print the versions, pins and image IDs to paste into docs/lez-setup.md
#   lez_all               up, deploy, account, call (stack must be built)

if [ "${BASH_SOURCE[0]}" = "$0" ]; then
  echo "source this file: source scripts/lez-env.sh" >&2
  exit 2
fi

LEZ_DIR="${LEZ_DIR:-./lez}"
LEZ_PROGRAM="${LEZ_PROGRAM:-hello_world}"
LEZ_ACCT="${LEZ_ACCT:-}"

# lgs and logos-scaffold are the same tool
_lez_bin() { command -v lgs >/dev/null 2>&1 && echo lgs || echo logos-scaffold; }
_lez_in() { ( cd "$LEZ_DIR" && "$@" ); }
_lez_scaf() { local b; b="$(_lez_bin)"; _lez_in env RISC0_DEV_MODE=1 "$b" "$@"; }

lez_check() {
  local ok=0 t
  for t in git rustc cargo curl lsof; do
    if command -v "$t" >/dev/null 2>&1; then echo "ok   $t  $("$t" --version 2>&1 | head -1)"; else echo "MISSING $t"; ok=1; fi
  done
  if command -v lgs >/dev/null 2>&1 || command -v logos-scaffold >/dev/null 2>&1; then
    echo "ok   $(_lez_bin)  $($(_lez_bin) --version 2>&1 | head -1)"
  else echo "MISSING lgs / logos-scaffold"; ok=1; fi
  if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then echo "ok   docker daemon running"
  elif command -v podman >/dev/null 2>&1; then echo "ok   podman present"
  else echo "MISSING docker or podman (daemon must run)"; ok=1; fi
  if command -v rzup >/dev/null 2>&1; then rzup show 2>&1 | head -12; else echo "MISSING rzup (risc0 toolchain)"; ok=1; fi
  return $ok
}

lez_new() {
  if [ -d "$LEZ_DIR" ]; then echo "$LEZ_DIR exists, not touching it" >&2; return 1; fi
  "$(_lez_bin)" new "$LEZ_DIR" --template lez-framework
}

lez_setup() { _lez_scaf setup && _lez_scaf doctor; }
lez_build() { _lez_scaf build; }
lez_up()    { _lez_scaf localnet start && _lez_scaf localnet status; }
lez_down()  { _lez_scaf localnet stop; }

lez_deploy() { _lez_scaf deploy "${1:-$LEZ_PROGRAM}"; }

lez_account() {
  local out
  out="$(_lez_in "$(_lez_bin)" wallet -- account new public 2>&1)" || { echo "$out" >&2; return 1; }
  echo "$out"
  LEZ_ACCT="$(printf '%s\n' "$out" | sed -n 's#.*Public/\([A-Za-z0-9]*\).*#\1#p' | head -1)"
  [ -n "$LEZ_ACCT" ] && echo "LEZ_ACCT=$LEZ_ACCT" || { echo "could not read the account ID, set LEZ_ACCT by hand" >&2; return 1; }
}

lez_call() {
  [ -n "$LEZ_ACCT" ] || { echo "run lez_account first, or set LEZ_ACCT" >&2; return 1; }
  local home; home="$(cd "$LEZ_DIR" && pwd)/.scaffold/wallet"
  _lez_in "$(_lez_bin)" wallet topup || true
  # The hello client binary name comes from the template; confirm it with `ls $LEZ_DIR/examples` or the template README
  ( cd "$LEZ_DIR" && NSSA_WALLET_HOME_DIR="$home" LEE_WALLET_HOME_DIR="$home" RISC0_DEV_MODE=1 \
      cargo run --bin "run_${LEZ_PROGRAM}" -- "$LEZ_ACCT" ) || return 1
  echo "wait for the next block, then:"
  sleep 15
  _lez_in "$(_lez_bin)" wallet -- account get --account-id "Public/$LEZ_ACCT"
}

lez_record() {
  echo "date:        $(date -u +%FT%TZ)"
  echo "os:          $(uname -sm)"
  echo "scaffold:    $($(_lez_bin) --version 2>&1 | head -1)"
  echo "rustc:       $(rustc --version)"
  command -v rzup >/dev/null 2>&1 && { echo "rzup:"; rzup show 2>&1 | sed 's/^/  /'; }
  if [ -f "$LEZ_DIR/scaffold.toml" ]; then echo "scaffold.toml pins:"; sed 's/^/  /' "$LEZ_DIR/scaffold.toml"; fi
  echo "image IDs (from the build output; also compare with a Linux build):"
  _lez_in sh -c 'grep -rhoE "[A-Za-z_]+(_ID|image_id)[^\n]{0,90}" target/riscv-guest 2>/dev/null | head -10' || true
}

lez_all() { lez_up && lez_deploy && lez_account && lez_call; }